import React, { useEffect, useRef, useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";
import { toast, ToastContainer } from "react-toastify";

const ApprovedCenterLayer = () => {
  const [centers, setCenters] = useState([]);
  const [loading, setLoading] = useState(false);
  
  // Pagination states
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCentres, setTotalCentres] = useState(0);
  const centresPerPage = 8;

  const navigate = useNavigate();
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  
  // Fetch only approved centres with pagination
  const fetchApprovedCentres = async (page = 1) => {
    try {
      setLoading(true);
      const res = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/centres/`,
        {
          params: {
            page: page,
            limit: centresPerPage
          }
        }
      ); // your API route for approved centres
      
      
      // Handle paginated response
      if (res.data.centres) {
        setCenters(res.data.centres);
        setCurrentPage(res.data.currentPage || page);
        setTotalPages(res.data.totalPages || 1);
        setTotalCentres(res.data.totalCentres || 0);
      } else if (Array.isArray(res.data)) {
        // Fallback for non-paginated response
        setCenters(res.data);
        setTotalPages(Math.ceil(res.data.length / centresPerPage));
        setTotalCentres(res.data.length);
      }
    } catch (error) {
      console.error("Failed to fetch approved centres", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchApprovedCentres(1);
  }, []);

  const triggerDelete = (centre) => {
    setSelectedCentre(centre);
    setShowDeleteModal(true);
  };

  const handleDeleteConfirm = async () => {
    if (!selectedCentre) return;
    const id = selectedCentre._id;
    try {
      await axios.delete(
        `${process.env.REACT_APP_BACKEND_URL}/api/centres/${id}`
      );
      toast.success("Centre deleted successfully.");
      fetchApprovedCentres(currentPage); // Refresh current page
    } catch (error) {
      console.error("Delete failed", error);
      toast.error("Failed to delete centre.");
    } finally {
      setShowDeleteModal(false);
      setSelectedCentre(null);
    }
  };

  const handleDeleteCancel = () => {
    setShowDeleteModal(false);
    setSelectedCentre(null);
  };

  const handleClick = async (centreId) => {
    navigate(`/services/${centreId}`);
  };

  const [name, setName] = useState("");
  const [type, setType] = useState("");
  const [searchTimeout, setSearchTimeout] = useState(null);

  // Search with debounce
  useEffect(() => {
    if (searchTimeout) clearTimeout(searchTimeout);
    
    const timeout = setTimeout(() => {
      const fetchData = async () => {
        try {
          setLoading(true);
          const response = await axios.get(
            `${process.env.REACT_APP_BACKEND_URL}/api/centres/search`,
            {
              params: {
                name: name.trim(),
                type: type.trim(),
                page: 1,
                limit: centresPerPage
              },
            },
          );
          
          // Handle paginated search response
          if (response.data.centres) {
            setCenters(response.data.centres);
            setCurrentPage(response.data.currentPage || 1);
            setTotalPages(response.data.totalPages || 1);
            setTotalCentres(response.data.totalCentres || 0);
          } else if (Array.isArray(response.data)) {
            setCenters(response.data);
            setTotalPages(Math.ceil(response.data.length / centresPerPage));
            setTotalCentres(response.data.length);
          }
        } catch (err) {
          console.error(err);
        } finally {
          setLoading(false);
        }
      };

      if (name.trim() !== "" || type.trim() !== "") {
        fetchData();
      } else {
        fetchApprovedCentres(1);
      }
    }, 500);
    
    setSearchTimeout(timeout);
    
    return () => clearTimeout(timeout);
  }, [name, type]);

  const [selectedCentre, setSelectedCentre] = useState(null);
  const [showViewModal, setShowViewModal] = useState(null);

  const modalRef = useRef(null);
  const viewModalRef = useRef(null);

  useEffect(() => {
    // Handle click outside
    const handleClickOutside = (event) => {
      if (
        modalRef.current &&
        !modalRef.current.contains(event.target) &&
        showViewModal
      ) {
        setShowViewModal(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    // 🔑 Scroll lock logic
    if (showViewModal) {
      document.body.style.overflow = "hidden"; // Disable background scroll
    } else {
      document.body.style.overflow = "auto"; // Enable background scroll
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.body.style.overflow = "auto"; // Cleanup when component unmounts
    };
  }, [showViewModal]);

  // Current centres for display (server already paginates)
  const currentCentres = centers;

  const handlePageChange = (pageNumber) => {
    setCurrentPage(pageNumber);
    
    if (name.trim() !== "" || type.trim() !== "") {
      // If searching, fetch search results for new page
      const fetchSearchData = async () => {
        try {
          setLoading(true);
          const response = await axios.get(
            `${process.env.REACT_APP_BACKEND_URL}/api/centres/search`,
            {
              params: {
                name: name.trim(),
                type: type.trim(),
                page: pageNumber,
                limit: centresPerPage
              },
            },
          );
          
          if (response.data.centres) {
            setCenters(response.data.centres);
            setCurrentPage(response.data.currentPage || pageNumber);
            setTotalPages(response.data.totalPages || 1);
            setTotalCentres(response.data.totalCentres || 0);
          }
        } catch (err) {
          console.error(err);
        } finally {
          setLoading(false);
        }
      };
      fetchSearchData();
    } else {
      fetchApprovedCentres(pageNumber);
    }
  };

  const handlePageChangeWithScroll = (page) => {
    handlePageChange(page);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const renderPagination = () => {
    const pages = [];
    const maxVisible = 3;
    let startPage = Math.max(1, currentPage - Math.floor(maxVisible / 2));
    let endPage = startPage + maxVisible - 1;

    if (endPage > totalPages) {
      endPage = totalPages;
      startPage = Math.max(1, endPage - maxVisible + 1);
    }

    pages.push(
      <li
        key="first"
        className={`page-item ${currentPage === 1 ? " disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() => currentPage !== 1 && handlePageChangeWithScroll(1)}
        >
          First
        </button>
      </li>,
    );

    // Prev Button
    pages.push(
      <li
        key="prev"
        className={`page-item ${currentPage === 1 ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() =>
            currentPage > 1 && handlePageChangeWithScroll(currentPage - 1)
          }
        >
          Prev
        </button>
      </li>,
    );

    // Page Numbers
    for (let i = startPage; i <= endPage; i++) {
      pages.push(
        <li
          key={i}
          className={`page-item ${currentPage === i ? "active" : ""}`}
        >
          <button
            className="page-link"
            onClick={() => handlePageChangeWithScroll(i)}
          >
            {i}
          </button>
        </li>,
      );
    }

    // Next Button
    pages.push(
      <li
        key="next"
        className={`page-item ${
          currentPage === totalPages ? "disabled" : ""
        }`}
      >
        <button
          className="page-link"
          onClick={() =>
            currentPage < totalPages &&
            handlePageChangeWithScroll(currentPage + 1)
          }
        >
          Next
        </button>
      </li>,
    );

    pages.push(
      <li
        key="last"
        className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}
      >
        <button
          className="page-link"
          onClick={() => handlePageChangeWithScroll(totalPages)}
        >
          Last
        </button>
      </li>,
    );

    return pages;
  };

  const toTitleCase = (str = "") => {
    return str
      .toLowerCase()
      .split(" ")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" ");
  };

  const handleExportCSV = async () => {
    try {
      setLoading(true);
      const response = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/centres/search`,
        {
          params: {
            name: name.trim(),
            type: type.trim(),
          },
        }
      );

      const allCentres = response.data.centres || [];
      if (allCentres.length === 0) {
        toast.info("No records to export.");
        return;
      }

      const headers = [
        "SN",
        "Centre Name",
        "Centre Type",
        "Email",
        "Phone Number",
        "Landline Number",
        "Address",
        "City",
        "State",
        "Zip Code",
        "Facilities",
        "DigiPin Location",
        "Authorized Person Name",
        "Authorized Person Designation",
        "Status",
        "Created At"
      ];

      const escapeCSVValue = (val) => {
        if (val === null || val === undefined) return '""';
        let stringVal = String(val);
        stringVal = stringVal.replace(/"/g, '""');
        return `"${stringVal}"`;
      };

      const csvContent = [
        headers.map(escapeCSVValue).join(","),
        ...allCentres.map((centre, index) => [
          index + 1,
          centre.centreName || "",
          centre.centreType || "",
          centre.email || "",
          centre.phoneNumber || "",
          centre.landlineNumber || "",
          centre.address || "",
          centre.city || "",
          centre.state || "",
          centre.zipCode || "",
          (centre.availableFacilities || []).join("; "),
          centre.digiPinLocation || "",
          centre.authorizedPerson?.name || "",
          centre.authorizedPerson?.designation || "",
          centre.status || "",
          centre.createdAt ? new Date(centre.createdAt).toLocaleDateString() : ""
        ].map(escapeCSVValue).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.setAttribute("href", url);
      link.setAttribute("download", `approved_centres_${new Date().toISOString().slice(0, 10)}.csv`);
      link.style.visibility = "hidden";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      toast.success("CSV exported successfully!");
    } catch (error) {
      console.error("Failed to export CSV", error);
      toast.error("Failed to export CSV.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="dashboard-body__content">
      <div style={{ display: "flex", justifyContent: "flex-end" }}></div>

      <div className="card common-card border border-gray-five">
        <div className="approved-centres-header">
          <h4>Approved Centres</h4>

          <div className="search-container">
            <input
              type="text"
              className="common-input border-gray-five"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Search by Centre Name"
              style={{ flex: "1 1 200px", minWidth: "150px" }}
            />

            <select
              className="common-input border-gray-five"
              value={type}
              onChange={(e) => setType(e.target.value)}
              style={{ flex: "1 1 150px", minWidth: "150px" }}
            >
              <option value="">Select Type</option>
              <option value="Hospital">Hospital</option>
              <option value="General Clinic">General Clinic</option>
              <option value="Dental Care Centre">Dental Care Centre</option>
              <option value="Labs and Diagnostic">Labs and Diagnostic</option>
              <option value="Ayush Centre">Ayush Centre</option>
              <option value="Miscellaneous Healthcare Centre">
                Miscellaneous Healthcare Centre
              </option>
            </select>

            <button
              onClick={handleExportCSV}
              className="btn btn-primary btn-sm"
              style={{
                display: "flex",
                alignItems: "center",
                gap: "5px",
                backgroundColor: "#A847F0",
                borderColor: "#A847F0",
                color: "#fff",
                height: "42px",
                padding: "0 20px",
                borderRadius: "8px",
                fontWeight: "600",
                cursor: "pointer"
              }}
            >
              Export CSV
            </button>
          </div>
        </div>

        <div className="card-body">
          {loading ? (
            <p>Loading...</p>
          ) : currentCentres.length > 0 ? (
            <div className="table-responsive" style={{ marginTop: "-25px" }}>
              <table className="table text-body">
                <thead>
                  <tr>
                    <th>SN.</th>
                    <th>Centre Name</th>
                    <th>Centre Type</th>
                    <th>Total Services</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {currentCentres.map((centre, index) => (
                    <tr key={centre._id}>
                      <td>{(currentPage - 1) * centresPerPage + index + 1}</td>
                      <td>
                        <Link
                          to={`/services/${centre._id}`}
                          style={{ textDecoration: "underline" }}
                        >
                          {toTitleCase(centre.centreName)}
                        </Link>
                      </td>
                      <td>{centre.centreType}</td>
                      <td>{centre.totalServices || 0}</td>
                      <td>
                        <button
                          className="btn btn-sm btn-info"
                          onClick={() => {
                            setSelectedCentre(centre);
                            setShowViewModal("details");
                          }}
                          style={{ backgroundColor: "blue", color: "white", marginRight: "5px" }}
                        >
                          View
                        </button>
                        <button
                          className="btn btn-sm btn-danger"
                          onClick={() => triggerDelete(centre)}
                          style={{ backgroundColor: "red", color: "white" }}
                        >
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p className="text-muted">No approved centres found.</p>
          )}
          
          {/* Pagination */}
          {currentCentres.length > 0 && totalPages > 1 && (
            <nav aria-label="Service pagination" className="mt-3">
              <ul className="pagination justify-content-center">
                {renderPagination()}
              </ul>
            </nav>
          )}
        </div>
      </div>
      <ToastContainer position="top-right" autoClose={3000} />

      {showViewModal && selectedCentre && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: "rgba(0,0,0,0.5)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 1000,
          }}
        >
          <div
            ref={viewModalRef}
            style={{
              backgroundColor: "#fff",
              borderRadius: "10px",
              maxHeight: "95vh",
              maxWidth: "800px",
              width: "95%",
              boxShadow: "0 0 10px rgba(0,0,0,0.3)",
              position: "absolute",
              overflowY: "scroll",
              /* Hide scrollbar cross-browser */
              scrollbarWidth: "none", // Firefox
              msOverflowStyle: "none",
            }}
            className="no-scrollbar"
          >
            <div
              style={{
                backgroundColor: "#3a3a3a",
                color: "#fff",
                padding: "15px 20px",
                fontSize: "18px",
                fontWeight: "bold",
                position: "sticky",
                top: "0",
                zIndex: 10,
              }}
            >
              Centre Details
              <button
                onClick={() => setShowViewModal(false)}
                style={{
                  position: "absolute",
                  top: "10px",
                  right: "10px",
                  background: "transparent",
                  border: "none",
                  fontSize: "22px",
                  color: "#fff",
                  cursor: "pointer",
                }}
              >
                &times;
              </button>
            </div>

            <div
              style={{
                display: "flex",
                flexWrap: "wrap",
                padding: "20px",
                gap: "20px",
                color: "#333",
              }}
            >
              {/* Left Column */}
              <div style={{ flex: 1, minWidth: "250px" }}>
                <div style={{ marginBottom: "15px" }}>
                  <strong>Centre Name</strong>
                  <p>{selectedCentre.centreName}</p>
                </div>
                <div style={{ marginBottom: "15px" }}>
                  <strong>Centre Type</strong>
                  <p>{selectedCentre.centreType}</p>
                </div>
                <div style={{ marginBottom: "15px" }}>
                  <strong>Email</strong>
                  <p>{selectedCentre.email}</p>
                </div>
                <div style={{ marginBottom: "15px" }}>
                  <strong>Phone</strong>
                  <p>{selectedCentre.phoneNumber}</p>
                </div>
                <div style={{ marginBottom: "15px" }}>
                  <strong>Landline</strong>
                  <p>
                    {selectedCentre.landlineNumber || "Landline not available"}
                  </p>
                </div>
                <div style={{ marginBottom: "15px" }}>
                  <strong>Address</strong>
                  <p>{selectedCentre.address}</p>
                </div>
                <div style={{ marginBottom: "15px" }}>
                  <strong>ZIP Code</strong>
                  <p>{selectedCentre.zipCode}</p>
                </div>

                <div style={{ marginBottom: "15px" }}>
                  <strong>City</strong>
                  <p>{selectedCentre.city}</p>
                </div>

                <div style={{ marginBottom: "15px" }}>
                  <strong>State</strong>
                  <p>{selectedCentre.state}</p>
                </div>
              </div>

              {/* Right Column */}
              <div style={{ flex: 1, minWidth: "250px" }}>
                <div style={{ marginBottom: "15px" }}>
                  <strong style={{ color: "black" }}>Facilities</strong>
                  <ul style={{ marginTop: "5px" }}>
                    {selectedCentre.availableFacilities?.length ? (
                      selectedCentre.availableFacilities.map(
                        (facility, index) => <li key={index}>{facility}</li>,
                      )
                    ) : (
                      <li>None</li>
                    )}
                  </ul>
                </div>

                <div style={{ marginBottom: "15px" }}>
                  <strong>DigiPin Location</strong>
                  <p>
                    {selectedCentre.digiPinLocation || "DigiPin not available"}
                  </p>
                </div>
                <div style={{ marginBottom: "15px" }}>
                  <strong>Authorized Person</strong>
                  <p>
                    Name: {selectedCentre.authorizedPerson?.name || "N/A"} <br />
                    Designation:{" "}
                    {selectedCentre.authorizedPerson?.designation || "N/A"}
                  </p>
                  {selectedCentre.authorizedPerson?.authDocument && (
                    <a
                      href={selectedCentre.authorizedPerson.authDocument}
                      target="_blank"
                      rel="noopener noreferrer"
                      style={{
                        display: "inline-block",
                        marginTop: "5px",
                        fontSize: "14px",
                        color: "#007bff",
                      }}
                    >
                      View Document
                    </a>
                  )}
                </div>

                {selectedCentre.documents?.length > 0 && (
                  <div style={{ marginBottom: "15px" }}>
                    <strong style={{ color: "black" }}>Documents</strong>
                    <ul style={{ marginTop: "5px" }}>
                      {selectedCentre.documents.map((doc, index) => (
                        <li key={index}>
                          {doc.docType} -{" "}
                          <a
                            href={doc.docFile}
                            target="_blank"
                            rel="noopener noreferrer"
                            style={{ color: "#007bff", fontSize: "14px" }}
                          >
                            View Document
                          </a>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`.approved-centres-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  margin: 20px 30px;
  gap: 10px;
}

.approved-centres-header h4 {
  margin: 0;
  font-weight: bold;
  color: #333;
  flex: 1 1 auto;
}

.approved-centres-header .search-container {
  display: flex;
  gap: 10px;
  flex: 1 1 auto;
  justify-content: flex-end;
  flex-wrap: wrap;
}

@media (max-width: 768px) {
  .approved-centres-header h4 {
    flex: 1 1 100%;
    margin-bottom: 10px;
  }
  .approved-centres-header .search-container {
    flex: 1 1 100%;
    justify-content: flex-start;
  }
}
`}</style>

      {showDeleteModal && selectedCentre && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: "rgba(0,0,0,0.5)",
            backdropFilter: "blur(6px)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999,
          }}
        >
          <div
            style={{
              backgroundColor: "#fff",
              borderRadius: "16px",
              maxWidth: "500px",
              width: "90%",
              boxShadow: "0 20px 40px rgba(0, 0, 0, 0.15)",
              overflow: "hidden",
              // border: "1px solid rgba(0,0,0,0.05)",
              animation: "modalFadeIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)"
            }}
          >
            {/* Header */}
            <div
              style={{
                background: "linear-gradient(135deg, #ef4444 0%, #dc2626 100%)",
                color: "#fff",
                padding: "16px 20px",
                fontSize: "18px",
                fontWeight: "700",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
              }}
            >
              <span>⚠️ Confirm Cascade Deletion</span>
              <button
                onClick={handleDeleteCancel}
                style={{
                  background: "rgba(255,255,255,0.15)",
                  border: "none",
                  width: "28px",
                  height: "28px",
                  borderRadius: "50%",
                  color: "#fff",
                  cursor: "pointer",
                  fontSize: "16px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center"
                }}
              >
                &times;
              </button>
            </div>

            {/* Body */}
            <div style={{ padding: "24px 20px" }}>
              <p style={{ color: "#1e293b", fontSize: "15px", fontWeight: "600", marginBottom: "16px" }}>
                Are you sure you want to completely delete <span style={{ color: "#dc2626", fontWeight: "800" }}>{selectedCentre.centreName}</span>?
              </p>

              <div style={{ background: "#fef2f2", borderLeft: "4px solid #ef4444", padding: "12px 16px", borderRadius: "8px", marginBottom: "20px" }}>
                <p style={{ color: "#b91c1c", fontSize: "13px", fontWeight: "700", textTransform: "uppercase", letterSpacing: "0.5px", margin: "0 0 6px 0" }}>
                  Warning: The following will be permanently deleted:
                </p>
                <ul style={{ color: "#991b1b", fontSize: "13px", margin: 0, paddingLeft: "18px", lineHeight: "1.6" }}>
                  <li>All <strong>Services</strong> created by this centre</li>
                  <li>All <strong>Packages</strong> offered by this centre</li>
                  <li>All <strong>Doctors</strong> profiles registered under this centre</li>
                </ul>
              </div>

              <div style={{ background: "#f0fdf4", borderLeft: "4px solid #22c55e", padding: "12px 16px", borderRadius: "8px", marginBottom: "4px" }}>
                <p style={{ color: "#166534", fontSize: "13px", fontWeight: "700", textTransform: "uppercase", letterSpacing: "0.5px", margin: "0 0 4px 0" }}>
                  🔒 Preserved Data:
                </p>
                <p style={{ color: "#15803d", fontSize: "13px", margin: 0, lineHeight: "1.4" }}>
                  Patients' <strong>Booking history</strong> and uploaded medical <strong>Reports</strong> will be preserved safely.
                </p>
              </div>
            </div>

            {/* Footer */}
            <div
              style={{
                padding: "16px 20px 24px 20px",
                display: "flex",
                gap: "12px",
                justifyContent: "flex-end",
                borderTop: "1px solid #f1f5f9",
                background: "#fafbfd"
              }}
            >
              <button
                onClick={handleDeleteCancel}
                style={{
                  backgroundColor: "#f1f5f9",
                  color: "#475569",
                  border: "none",
                  borderRadius: "8px",
                  padding: "10px 18px",
                  fontSize: "14px",
                  fontWeight: "600",
                  cursor: "pointer",
                  transition: "background 0.2s"
                }}
                onMouseOver={(e) => e.currentTarget.style.backgroundColor = "#e2e8f0"}
                onMouseOut={(e) => e.currentTarget.style.backgroundColor = "#f1f5f9"}
              >
                Cancel
              </button>
              <button
                onClick={handleDeleteConfirm}
                style={{
                  backgroundColor: "#ef4444",
                  color: "#fff",
                  border: "none",
                  borderRadius: "8px",
                  padding: "10px 18px",
                  fontSize: "14px",
                  fontWeight: "600",
                  cursor: "pointer",
                  boxShadow: "0 4px 12px rgba(239, 68, 68, 0.2)",
                  transition: "background 0.2s"
                }}
                onMouseOver={(e) => e.currentTarget.style.backgroundColor = "#dc2626"}
                onMouseOut={(e) => e.currentTarget.style.backgroundColor = "#ef4444"}
              >
                Confirm Delete
              </button>
            </div>
          </div>
          <style>
            {`
              @keyframes modalFadeIn {
                from { transform: translateY(15px); opacity: 0; }
                to { transform: translateY(0); opacity: 1; }
              }
            `}
          </style>
        </div>
      )}
    </div>
  );
};

export default ApprovedCenterLayer;